import logging

from jsilib.jsonrpc.exc import ClientClosedError

from taf.fdsw.rc.clients.data import ClientData
from taf.fdsw.rc.clients.exceptions import ClientAuthenticationFailed
from taf.fdsw.rc.clients.websocket.jsilib.jsilib_connection import Connection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class JSILIBClient():

    def __init__(self, ip_address, port, username, password):
        self.ip_address = ip_address
        self.port = port

        self.username = username
        self.password = password
        self.auth_token = None

        self._connection = None
        self.notification_handler = None
        self.setup()

    def setup(self):
        """
        Initialize connection class and jsilib Thread, then connect using jsilib
        """
        self._connection = Connection()
        self._connection.prepare_jsonrpc_client(ip_address=self.ip_address, port=self.port)

    def connect(self):
        logger.debug("Acquiring access token")
        auth_response = self._connection.send(
            method='login',
            parameters={
                'username': self.username,
                'password': self.password})
        auth_token = auth_response.head.result
        if not auth_token:
            raise ClientAuthenticationFailed("Endpoint did not provide authentication token")
        self.auth_token = auth_token
        logger.debug("Authentication successful")

    def send(self, method, parameters=None, payload=None, timeout=None):
        resp = self._connection.send(method=method, parameters=parameters, payload=payload, sid=self.auth_token)
        application_data = ClientData(data=resp.head.result, payload=resp.body, error=resp.head.error)
        return application_data

    def subscribe_for_notifications(self, method):
        self._connection._set_subscriber(method=method)
        self._connection.notification_handler.subscribe(self.send)

    def flush_notifications(self):
        self._connection.notification_handler.flush_notifications()

    def search_for_notifications(self, keys):
        return self._connection.notification_handler.search_for_notifications(keys)

    def download_files(self, zip_path, timeout):  # TODO: tidy up namespace here
        self._connection.get_files(zip_path, self.auth_token, timeout)

    def get_diagnostics(self, method, path, timeout=None):
        return self._connection.get_diagnostics(method, path, self.auth_token, timeout)

    def disconnect(self):
        try:
            self._connection.send(method="logout", sid=self.auth_token)  # used send from Connection class to avoid reconnect mechanism
        except ClientClosedError:
            logger.debug("Client already closed!")
        finally:
            self._connection.disconnect()
